// make-bundle.mjs — concatenate the app's ~65 deferred scripts into ONE app-bundle.js
// so first load makes 1 JS request instead of 65 (big LCP/INP win on mobile networks).
//
// Safety model: all files are classic scripts loaded with `defer`, so they execute in
// document order sharing the global scope. Plain concatenation in the SAME order is
// semantically equivalent (top-level var/function/const behave identically across
// concatenated code and sequential classic scripts). We verify the result parses
// (`node --check` equivalent via new Function) and the smoke test exercises every route.
//
// The ordered manifest below mirrors index.html's script order EXACTLY (source of truth
// at the time of bundling). Files not listed here (vendor react, blog-data.js, lazy
// screens like sop-tool.js) stay separate on purpose.
import { readFileSync, writeFileSync, existsSync } from "fs";
import path from "path";
import { fileURLToPath } from "url";

const ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), "..");

const MANIFEST = [
  "data.js", "gemini-tts.js", "seo.js", "test-catalog.js", "normalize-test.js",
  "learning-hub-catalog.js", "visual-renderer.js", "auth.js", "reminders.js", "md.js",
  "ai-tutor.js", "chatbot-widget.js",
  "screens/pte-renderer.js", "screens/pte-listening-renderer.js", "screens/pte-sw-renderer.js",
  "screens/celpip-renderer.js", "screens/home.js", "screens/guide.js", "screens/learning-club.js",
  "screens/error-log.js", "screens/progress.js", "screens/exam-prep.js", "screens/college-tools.js",
  "screens/calculators.js", "scholarship-data.js", "screens/scholarship-tool.js", "country-data.js",
  "live-data.js", "firebase-config.js", "country-landmarks.js", "screens/destinations.js",
  "screens/counsellor.js", "screens/profile-eval.js", "screens/compare.js", "screens/apply-partners.js",
  "screens/visa-interview.js", "screens/onboarding.js", "screens/community.js", "screens/leaderboard.js",
  "focus-engine.js", "screens/focus-timer.js", "screens/focus-widget.js", "screens/tools.js",
  "screens/colleges.js", "screens/study-planner.js", "language-data.js", "screens/languages.js",
  "screens/lang-speaking.js", "lang-mock-data.js", "screens/lang-mock.js", "screens/slide-deck.js",
  "screens/learn-hub.js", "gamify.js", "share-card.js", "referral.js", "vocab-data.js",
  "lang-stories-data.js", "sa-extra-data.js", "screens/vocabulary.js", "screens/relocate.js",
  "screens/test-finder.js", "screens/achievements.js", "screens/band-checker.js", "app.js", "pro.js",
];

let out = "/* app-bundle.js — generated by scripts/make-bundle.mjs; DO NOT EDIT.\n" +
  "   Concatenation of the app's deferred scripts in index.html order (1 request instead of ~65). */\n";
let missing = [];
for (const f of MANIFEST) {
  const p = path.join(ROOT, f);
  if (!existsSync(p)) { missing.push(f); continue; }
  out += "\n/* ══════════ " + f + " ══════════ */\n;" + readFileSync(p, "utf8") + "\n;";
}
if (missing.length) {
  console.error("[bundle] MISSING files (aborting):", missing.join(", "));
  process.exit(1);
}
// Parse-check the whole bundle so a top-level const collision or syntax error fails the
// build here (loudly) instead of white-screening users.
try { new Function(out); } catch (e) {
  console.error("[bundle] bundle does not parse:", e.message);
  process.exit(1);
}
writeFileSync(path.join(ROOT, "app-bundle.js"), out);
console.log(`[bundle] app-bundle.js written — ${MANIFEST.length} files, ${(out.length / 1024).toFixed(0)} KB`);
